insert into occupations (code, title, description, job_zone, median_wage, growth_pct, source_ids) values
  ('19-1031.02', 'Range Managers', 'Research or study range land management practices to provide sustained production of forage, livestock, and wildlife.', 4, 73010, 5.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1031.03', 'Park Naturalists', 'Plan, develop, and conduct programs to inform public of historical, natural, and scientific features of national, state, or local park.', 4, 73010, 5.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1032.00', 'Foresters', 'Manage public and private forested lands for economic, recreational, and conservation purposes. May inventory the type, amount, and location of standing timber, appraise the timber''s worth, negotiate the purchase, and draw up contracts for procurement. May determine how to conserve wildlife habitats, creek beds, water quality, and soil stability, and how best to comply with environmental regulations. May devise plans for planting and growing new trees, monitor trees for healthy growth, and determine optimal harvesting schedules.', 4, 76400, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1041.00', 'Epidemiologists', 'Investigate and describe the determinants and distribution of disease, disability, or health outcomes. May develop the means for prevention and control.', 5, 87220, 18.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1042.00', 'Medical Scientists, Except Epidemiologists', 'Conduct research dealing with the understanding of human diseases and the improvement of human health. Engage in clinical investigation, research and development, or other related activities.', 5, 103410, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2011.00', 'Astronomers', 'Observe, research, and interpret astronomical phenomena to increase basic knowledge or apply such information to practical problems.', 5, 128820, 7.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2012.00', 'Physicists', 'Conduct research into physical phenomena, develop theories on the basis of observation and experiments, and devise methods to apply physical laws and theories.', 5, 172250, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2021.00', 'Atmospheric and Space Scientists', 'Investigate atmospheric phenomena and interpret meteorological data, gathered by surface and air stations, satellites, and radar to prepare reports and forecasts for public and other uses. Includes weather analysts and forecasters whose functions require the detailed knowledge of meteorology.', 4, 99070, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2031.00', 'Chemists', 'Conduct qualitative and quantitative chemical analyses or experiments in laboratories for quality or process control or to develop new products or knowledge.', 4, 91240, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2032.00', 'Materials Scientists', 'Research and study the structures and chemical properties of various natural and synthetic or composite materials, including metals, alloys, rubber, ceramics, semiconductors, polymers, and glass. Determine ways to strengthen or combine materials or develop new materials with new or specific properties for use in a variety of products and applications. Includes glass scientists, ceramic scientists, metallurgical scientists, and polymer scientists.', 4, 117790, 8.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.00', 'Environmental Scientists and Specialists, Including Health', 'Conduct research or perform investigation for the purpose of identifying, abating, or eliminating sources of pollutants or hazards that affect either the environment or public health. Using knowledge of various scientific disciplines, may collect, synthesize, study, report, and recommend action based on data derived from measurements or observations of air, food, soil, water, and other sources.', 4, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.01', 'Climate Change Policy Analysts', 'Research and analyze policy developments related to climate change. Make climate-related recommendations for actions such as legislation, awareness campaigns, or fundraising approaches.', 5, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.02', 'Environmental Restoration Planners', 'Collaborate with field and biology staff to oversee the implementation of restoration projects and to develop new products. Process and synthesize complex scientific data into practical strategies for restoration, monitoring or management.', 5, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.03', 'Industrial Ecologists', 'Apply principles and processes of natural ecosystems to develop models for efficient industrial systems. Use knowledge from the physical and social sciences to maximize effective use of natural resources in the production and use of goods and services. Examine societal issues and their relationship with both technical systems and the environment.', 5, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2042.00', 'Geoscientists, Except Hydrologists and Geographers', 'Study the composition, structure, and other physical aspects of the Earth. May use geological, physics, and mathematics knowledge in exploration for oil, gas, minerals, or underground water; or in waste disposal, land reclamation, or other environmental problems. May study the Earth''s internal composition, atmospheres, and oceans, and its magnetic, electrical, and gravitational forces. Includes mineralogists, paleontologists, stratigraphers, geodesists, and seismologists.', 4, 101920, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2043.00', 'Hydrologists', 'Research the distribution, circulation, and physical properties of underground and surface waters; and study the form and intensity of precipitation and its rate of infiltration into the soil, movement through the earth, and return to the ocean and atmosphere.', 4, 96600, 1.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2099.01', 'Remote Sensing Scientists and Technologists', 'Apply remote sensing principles and methods to analyze data and solve problems in areas such as natural resource management, urban planning, or homeland security. May develop new sensor systems, analytical techniques, or new applications for existing systems.', 4, 122570, 2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3011.00', 'Economists', 'Conduct research, prepare reports, or formulate plans to address economic problems related to the production and distribution of goods and services or monetary and fiscal policy. May collect and process economic and statistical data using sampling techniques and econometric methods.', 5, 124720, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3011.01', 'Environmental Economists', 'Conduct economic analysis related to environmental protection and use of the natural environment, such as water, air, land, and renewable energy resources. Evaluate and quantify benefits, costs, incentives, and impacts of alternative options using economic principles and statistical techniques.', 5, 124720, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3022.00', 'Survey Researchers', 'Plan, develop, or conduct surveys. May analyze and interpret the meaning of survey data, determine survey objectives, or suggest or test question wording. Includes social scientists who primarily design questionnaires or supervise survey teams.', 5, 69460, -4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3032.00', 'Industrial-Organizational Psychologists', 'Apply principles of psychology to human resources, administration, management, sales, and marketing problems. Activities may include policy planning; employee testing and selection, training, and development; and organizational development and analysis. May work with management to organize the work setting to improve worker productivity.', 5, 193950, 6.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3033.00', 'Clinical and Counseling Psychologists', 'Assess, diagnose, and treat mental and emotional disorders of individuals through observation, interview, and psychological tests. Help individuals with distress or maladjustment understand their problems through their knowledge of case history, interviews with patients, and theory. Provide individual or group counseling services to assist individuals in achieving more effective personal, social, educational, and vocational development and adjustment. May design behavior modification programs and consult with medical personnel regarding the best treatment for patients.', 5, 100580, 11.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3034.00', 'School Psychologists', 'Diagnose and implement individual or schoolwide interventions or strategies to address educational, behavioral, or developmental issues that adversely impact educational functioning in a school. May address student learning and behavioral problems and counsel students or families. May design and implement performance plans, and evaluate performance. May consult with other school-based personnel.', 5, 95990, 0.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3039.02', 'Neuropsychologists', 'Apply theories and principles of neuropsychology to evaluate and diagnose disorders of higher cerebral functioning, often in research and medical settings. Study the human brain and the effect of physiological states on human cognition and behavior. May formulate and administer programs of treatment.', 5, 110840, 2.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3039.03', 'Clinical Neuropsychologists', 'Assess and diagnose patients with neurobehavioral problems related to acquired or developmental disorders of the nervous system, such as neurodegenerative disorders, traumatic brain injury, seizure disorders, and learning disabilities. Recommend treatment after diagnosis, such as therapy, medication, or surgery. Assist with evaluation before and after neurosurgical procedures, such as deep brain stimulation.', 5, 110840, 2.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3041.00', 'Sociologists', 'Study human society and social behavior by examining the groups and social institutions that people form, as well as various social, religious, political, and business organizations. May study the behavior and interaction of groups, trace their origin and growth, and analyze the influence of group activities on individual members.', 5, 106030, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3051.00', 'Urban and Regional Planners', 'Develop comprehensive plans and programs for use of land and physical facilities of jurisdictions, such as towns, cities, counties, and metropolitan areas.', 5, 89320, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3091.00', 'Anthropologists and Archeologists', 'Study the origin, development, and behavior of human beings. May study the way of life, language, or physical characteristics of people in various parts of the world. May engage in systematic recovery and examination of material evidence, such as tools or pottery remaining from past human cultures, in order to determine the history, customs, and living habits of earlier civilizations.', 5, 70770, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3092.00', 'Geographers', 'Study the nature and use of areas of the Earth''s surface, relating and interpreting interactions of physical and cultural phenomena. Conduct research on physical aspects of a region, including land forms, climates, soils, plants, and animals, and conduct research on the spatial implications of human activities within a given area, including social characteristics, economic activities, and political organization, as well as researching interdependence between regions at scales ranging from local to global.', 4, 102040, -2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3093.00', 'Historians', 'Research, analyze, record, and interpret the past as recorded in sources, such as government and institutional records, newspapers and other periodicals, photographs, interviews, films, electronic media, and unpublished manuscripts, such as personal diaries and letters.', 5, 76750, 3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3094.00', 'Political Scientists', 'Study the origin, development, and operation of political systems. May study topics, such as public opinion, political decisionmaking, and ideology. May analyze the structure and operation of governments, as well as various political entities. May conduct public opinion surveys, analyze election results, or analyze public documents.', 5, 142080, -2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3099.01', 'Transportation Planners', 'Prepare studies for proposed transportation projects. Gather, compile, and analyze data. Study the use and operation of transportation systems. Develop transportation models or simulations.', 4, 101110, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4012.00', 'Agricultural Technicians', 'Work with agricultural scientists in plant, fiber, and animal research, or assist with animal breeding and nutrition. Set up or maintain laboratory equipment and collect samples from crops or animals. Prepare specimens or record data to assist scientists in biology or related life science experiments. Conduct tests and experiments to improve yield and quality of crops or to increase the resistance of plants and animals to disease or insects.', 3, 49630, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4012.01', 'Precision Agriculture Technicians', 'Apply geospatial technologies, including geographic information systems (GIS) and Global Positioning System (GPS), to agricultural production or management activities, such as pest scouting, site-specific pesticide application, yield mapping, or variable-rate irrigation. May use computers to develop or analyze maps or remote sensing images to compare physical topography with data on soils, fertilizer, pests, or weather.', 3, 49630, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4013.00', 'Food Science Technicians', 'Work with food scientists or technologists to perform standardized qualitative and quantitative tests to determine physical or chemical properties of food or beverage products. Includes technicians who assist in research and development of production technology, quality control, packaging, processing, and use of foods.', 3, 52130, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4021.00', 'Biological Technicians', 'Assist biological and medical scientists. Set up, operate, and maintain laboratory instruments and equipment, monitor experiments, collect data and samples, make observations, and calculate and record results. May analyze organic substances, such as blood, food, and drugs.', 4, 57510, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4031.00', 'Chemical Technicians', 'Conduct chemical and physical laboratory tests to assist scientists in making qualitative and quantitative analyses of solids, liquids, and gaseous materials for research and development of new products or processes, quality control, maintenance of environmental standards, and other work involving experimental, theoretical, or practical application of chemistry and related sciences.', 3, 60390, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4042.00', 'Environmental Science and Protection Technicians, Including Health', 'Perform laboratory and field tests to monitor the environment and investigate sources of pollution, including those that affect health, under the direction of an environmental scientist, engineer, or other specialist. May collect samples of gases, soil, water, and other materials for testing.', 4, 55090, 6.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4043.00', 'Geological Technicians, Except Hydrologic Technicians', 'Assist scientists or engineers in the use of electronic, sonic, or nuclear measuring instruments in laboratory, exploration, and production activities to obtain data indicating resources such as metallic ore, minerals, gas, coal, or petroleum. Analyze mud and drill cuttings. Chart pressure, temperature, and other characteristics of wells or bore holes.', 4, 53350, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4044.00', 'Hydrologic Technicians', 'Collect and organize data concerning the distribution and circulation of ground and surface water, and data on its physical, chemical, and biological properties. Measure and report on flow rates and ground water levels, maintain field equipment, collect water samples, install and collect sampling equipment, and process samples for shipment to testing laboratories. May collect data on behalf of hydrologists, engineers, developers, government agencies, or agriculture.', 3, 64790, -1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4051.00', 'Nuclear Technicians', 'Assist nuclear physicists, nuclear engineers, or other scientists in laboratory, power generation, or electricity production activities. May operate, maintain, or provide quality control for nuclear testing and research equipment. May monitor radiation.', 3, 110240, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4051.02', 'Nuclear Monitoring Technicians', 'Collect and test samples to monitor results of nuclear experiments and contamination of humans, facilities, and environment.', 3, 110240, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4061.00', 'Social Science Research Assistants', 'Assist social scientists in laboratory, survey, and other social science research. May help prepare findings for publication and assist in laboratory analysis, quality control, or data management.', 4, 61990, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4071.00', 'Forest and Conservation Technicians', 'Provide technical assistance regarding the conservation of soil, water, forests, or related natural resources. May compile data pertaining to size, content, condition, and other characteristics of forest tracts under the direction of foresters, or train and lead forest workers in forest propagation and fire prevention and suppression. May assist conservation scientists in managing, improving, and protecting rangelands and wildlife habitats.', 3, 54560, -2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4092.00', 'Forensic Science Technicians', 'Collect, identify, classify, and analyze physical evidence related to criminal investigations. Perform tests on weapons or substances, such as fiber, hair, and tissue to determine significance to investigation. May testify as expert witnesses on evidence or crime laboratory techniques. May serve as specialists in area of expertise, such as ballistics, fingerprinting, handwriting, or biochemistry.', 3, 72060, 13.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4099.01', 'Quality Control Analysts', 'Conduct tests to determine quality of raw materials, bulk intermediate and finished products. May conduct stability sample tests.', 3, 62280, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4099.03', 'Remote Sensing Technicians', 'Apply remote sensing technologies to assist scientists in areas such as natural resources, urban planning, or homeland security. May prepare flight plans or sensor configurations for flight trips.', 4, 62280, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-5011.00', 'Occupational Health and Safety Specialists', 'Review, evaluate, and analyze work environments and design programs and procedures to control, eliminate, and prevent disease or injury caused by chemical, physical, and biological agents or ergonomic factors. May conduct inspections and enforce adherence to laws and regulations governing the health and safety of individuals. May be employed in the public or private sector.', 4, 90150, 18.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-5012.00', 'Occupational Health and Safety Technicians', 'Collect data on work environments for analysis by occupational health and safety specialists. Implement and conduct evaluation of programs designed to limit chemical, physical, biological, and ergonomic risks to workers.', 3, 61560, 19.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1011.00', 'Substance Abuse and Behavioral Disorder Counselors', 'Counsel and advise individuals with alcohol, tobacco, drug, or other problems, such as gambling and eating disorders. May counsel individuals, families, or groups or engage in prevention programs.', 5, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1012.00', 'Educational, Guidance, and Career Counselors and Advisors', 'Advise and assist students and provide educational and vocational guidance services.', 5, 64330, 2.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1013.00', 'Marriage and Family Therapists', 'Diagnose and treat mental and emotional disorders, whether cognitive, affective, or behavioral, within the context of marriage and family systems. Apply psychotherapeutic and family systems theories and techniques in the delivery of services to individuals, couples, and families for the purpose of treating such diagnosed nervous and mental disorders.', 5, 66940, 13.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1014.00', 'Mental Health Counselors', 'Counsel and advise individuals and groups to promote optimum mental and emotional health, with an emphasis on prevention. May help individuals deal with a broad range of mental health issues, such as those associated with addictions and substance abuse; family, parenting, and marital problems; stress management; self-esteem; or aging.', 5, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1015.00', 'Rehabilitation Counselors', 'Counsel individuals to maximize the independence and employability of persons coping with personal, social, and vocational difficulties that result from birth defects, illness, disease, accidents, aging, or the stress of daily life. Coordinate activities for residents of care and treatment facilities. Assess client needs and design and implement rehabilitation programs that may include personal and vocational counseling, training, and job placement.', 5, 46850, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1021.00', 'Child, Family, and School Social Workers', 'Provide social services and assistance to improve the social and psychological functioning of children and their families and to maximize the family well-being and the academic functioning of children. May assist parents, arrange adoptions, and find foster homes for abandoned or abused children. In schools, they address such problems as teenage pregnancy, misbehavior, and truancy. May also advise teachers.', 4, 59550, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1022.00', 'Healthcare Social Workers', 'Provide individuals, families, and groups with the psychosocial support needed to cope with chronic, acute, or terminal illnesses. Services include advising family caregivers. Provide patients with information and counseling, and make referrals for other services. May also provide case and care management or interventions designed to promote health, prevent disease, and address barriers to access to healthcare.', 5, 67880, 8.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1023.00', 'Mental Health and Substance Abuse Social Workers', 'Assess and treat individuals with mental, emotional, or substance abuse problems, including abuse of alcohol, tobacco, and/or other drugs. Activities may include individual and group therapy, crisis intervention, case management, client advocacy, prevention, and education.', 5, 60280, 10.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1091.00', 'Health Education Specialists', 'Provide and manage health education programs that help individuals, families, and their communities maximize and maintain healthy lifestyles. Use data to identify community needs prior to planning, implementing, monitoring, and evaluating programs designed to encourage healthy lifestyles, policies, and environments. May link health systems, health providers, insurers, and patients to address individual and population health needs. May serve as resource to assist individuals, other health professionals, or the community, and may administer fiscal resources for health education programs.', 4, 64070, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1092.00', 'Probation Officers and Correctional Treatment Specialists', 'Provide social services to assist in rehabilitation of law offenders in custody or on probation or parole. Make recommendations for actions involving formulation of rehabilitation plan and treatment of offender, including conditional release and education and employment stipulations.', 4, 66270, 3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1093.00', 'Social and Human Service Assistants', 'Assist other social and human service providers in providing client services in a wide variety of fields, such as psychology, rehabilitation, or social work, including support for families. May assist clients in identifying and obtaining available benefits and social and community services. May assist social workers with developing, organizing, and conducting programs to prevent and resolve problems relevant to substance abuse, human relationships, rehabilitation, or dependent care.', 4, 45930, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1094.00', 'Community Health Workers', 'Promote health within a community by assisting individuals to adopt healthy behaviors. Serve as an advocate for the health needs of individuals by assisting community residents in effectively communicating with healthcare providers or social service agencies. Act as liaison or advocate and implement programs that promote, maintain, and improve individual and overall community health. May deliver health-related preventive services such as blood pressure, glaucoma, and hearing screenings. May collect data to help identify community health needs.', 4, 51850, 12.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-2011.00', 'Clergy', 'Conduct religious worship and perform other spiritual functions associated with beliefs and practices of religious faith or denomination. Provide spiritual and moral guidance and assistance to members.', 5, 60810, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-2021.00', 'Directors, Religious Activities and Education', 'Coordinate or design programs and conduct outreach to promote the religious education or activities of a denominational group. May provide counseling, guidance, and leadership relative to marital, health, financial, and religious problems.', 4, 52100, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1011.00', 'Lawyers', 'Represent clients in criminal and civil litigation and other legal proceedings, draw up legal documents, or manage or advise clients on legal transactions. May specialize in a single area or may practice broadly in many areas of law.', 5, 159670, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1012.00', 'Judicial Law Clerks', 'Assist judges in court or by conducting research or preparing legal documents.', 5, 64920, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1021.00', 'Administrative Law Judges, Adjudicators, and Hearing Officers', 'Conduct hearings to recommend or make decisions on claims concerning government programs or other government-related matters. Determine liability, sanctions, or penalties, or recommend the acceptance or rejection of claims or settlements.', 5, 117860, 0, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1022.00', 'Arbitrators, Mediators, and Conciliators', 'Facilitate negotiation and conflict resolution through dialogue. Resolve conflicts outside of the court system by mutual consent of parties involved.', 5, 75530, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1023.00', 'Judges, Magistrate Judges, and Magistrates', 'Arbitrate, advise, adjudicate, or administer justice in a court of law. May sentence defendant in criminal cases according to government statutes or sentencing guidelines. May determine liability of defendant in civil cases. May perform wedding ceremonies.', 5, 153990, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-2011.00', 'Paralegals and Legal Assistants', 'Assist lawyers by investigating facts, preparing legal documents, or researching legal precedent. Conduct research to support a legal proceeding, to formulate a defense, or to initiate legal action.', 3, 62890, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2011.00', 'Preschool Teachers, Except Special Education', 'Instruct preschool-aged students, following curricula or lesson plans, in activities designed to promote social, physical, and intellectual growth.', 3, 38140, 4.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2012.00', 'Kindergarten Teachers, Except Special Education', 'Teach academic and social skills to kindergarten students.', 4, 62680, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2021.00', 'Elementary School Teachers, Except Special Education', 'Teach academic and social skills to students at the elementary school level.', 4, 63970, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2022.00', 'Middle School Teachers, Except Special and Career/Technical Education', 'Teach one or more subjects to students at the middle, intermediate, or junior high school level.', 4, 64370, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2023.00', 'Career/Technical Education Teachers, Middle School', 'Teach occupational, vocational, career, or technical subjects to students at the middle, intermediate, or junior high school level.', 4, 65030, -0.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2031.00', 'Secondary School Teachers, Except Special and Career/Technical Education', 'Teach one or more subjects to students at the secondary school level.', 4, 72040, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2032.00', 'Career/Technical Education Teachers, Secondary School', 'Teach occupational, vocational, career, or technical subjects to students at the secondary school level.', 4, 66270, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2051.00', 'Special Education Teachers, Preschool', 'Teach academic, social, and life skills to preschool-aged students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, 64830, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2055.00', 'Special Education Teachers, Kindergarten', 'Teach academic, social, and life skills to kindergarten students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2056.00', 'Special Education Teachers, Elementary School', 'Teach academic, social, and life skills to elementary school students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2057.00', 'Special Education Teachers, Middle School', 'Teach academic, social, and life skills to middle school students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, 66810, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2058.00', 'Special Education Teachers, Secondary School', 'Teach academic, social, and life skills to secondary school students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, 74260, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2059.01', 'Adapted Physical Education Specialists', 'Provide individualized physical education instruction or services to children, youth, or adults with exceptional physical needs due to gross motor developmental delays or other impairments.', 4, 76580, 1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3011.00', 'Adult Basic Education, Adult Secondary Education, and English as a Second Language Instructors', 'Teach or instruct out-of-school youths and adults in basic education, literacy, or English as a Second Language classes, or in classes for earning a high school equivalency credential.', 4, 61540, -13.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3021.00', 'Self-Enrichment Teachers', 'Teach or instruct individuals or groups for the primary purpose of self-enrichment or recreation, rather than for an occupational objective, educational attainment, competition, or fitness.', 3, 46800, 3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3031.00', 'Substitute Teachers, Short-Term', 'Teach students on a short-term basis as a temporary replacement for a regular classroom teacher, typically using the regular teacher''s lesson plan.', 4, 41670, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3041.00', 'Tutors', 'Instruct individual students or small groups of students in academic subjects to support formal class instruction or to prepare students for standardized or admissions tests.', 3, 43350, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4011.00', 'Archivists', 'Appraise, edit, and direct safekeeping of permanent records and historically valuable documents. Participate in research activities based on archival materials.', 5, 64550, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4012.00', 'Curators', 'Administer collections, such as artwork, collectibles, historic items, or scientific specimens of museums or other institutions. May conduct instructional, research, or public service activities of institution.', 5, 63420, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4013.00', 'Museum Technicians and Conservators', 'Restore, maintain, or prepare objects in museum collections for storage, research, or exhibit. May work with specimens such as fossils, skeletal parts, or botanicals; or artifacts, textiles, or art. May identify and record objects or install and arrange them in exhibits. Includes book or document conservators.', 5, 51440, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4022.00', 'Librarians and Media Collections Specialists', 'Administer and maintain libraries or collections of information, for public or private access through reference or borrowing. Work in a variety of settings, such as educational institutions, museums, and corporations, and with various types of informational materials, such as books, periodicals, recordings, films, and databases. Tasks may include acquiring, cataloging, and circulating library materials, and user services such as locating and organizing information, providing instruction on how to access information, and setting up and operating a library''s media equipment.', 5, 68270, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4031.00', 'Library Technicians', 'Assist librarians by helping readers in the use of library catalogs, databases, and indexes to locate books and other materials; and by answering questions that require only brief consultation of standard reference. Compile records; sort and shelve books or other media; remove or repair damaged books or other media; register patrons; and check materials in and out of the circulation process. Replace materials in shelving area (stacks) or files. Includes bookmobile drivers who assist with providing services in mobile libraries.', 3, 44580, -6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9021.00', 'Farm and Home Management Educators', 'Instruct and advise individuals and families engaged in agriculture, agricultural-related processes, or home management activities. Demonstrate procedures and apply research findings to advance agricultural and home management activities. May develop educational outreach programs. May instruct on either agricultural issues such as agricultural processes and techniques, pest management, and food safety, or on home management issues such as budgeting, nutrition, and child development.', 5, 60220, -3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9031.00', 'Instructional Coordinators', 'Develop instructional material, coordinate educational content, and incorporate current technology into instruction in order to provide guidelines to educators and instructors for developing curricula and conducting courses. May train and coach teachers. Includes educational consultants and specialists, and instructional material directors.', 5, 77440, 1.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9042.00', 'Teaching Assistants, Preschool, Elementary, Middle, and Secondary School, Except Special Education', 'Assist a preschool, elementary, middle, or secondary school teacher with instructional duties. Serve in a position for which a teacher has primary responsibility for the design and implementation of educational programs and services.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9043.00', 'Teaching Assistants, Special Education', 'Assist a preschool, elementary, middle, or secondary school teacher to provide academic, social, or life skills to students who have learning, emotional, or physical disabilities. Serve in a position for which a teacher has primary responsibility for the design and implementation of educational programs and services.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9044.00', 'Teaching Assistants, Postsecondary', 'Assist faculty or other instructional staff in postsecondary institutions by performing instructional support activities, such as developing teaching materials, leading discussion groups, preparing and giving examinations, and grading examinations or papers.', 5, 42910, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1011.00', 'Art Directors', 'Formulate design concepts and presentation approaches for visual productions and media, such as print, broadcasting, video, and film. Direct workers engaged in artwork or layout design.', 4, 114850, 4.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1012.00', 'Craft Artists', 'Create or reproduce handmade objects for sale and exhibition using a variety of techniques, such as welding, weaving, pottery, and needlecraft.', 3, 46080, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1013.00', 'Fine Artists, Including Painters, Sculptors, and Illustrators', 'Create original artwork using any of a wide variety of media and techniques.', 3, 55490, -2.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1014.00', 'Special Effects Artists and Animators', 'Create special effects or animations using film, video, computers, or other electronic tools and media for use in products, such as computer games, movies, music videos, and commercials.', 4, 102030, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2'])
insert into occupations (code, title, description, job_zone, median_wage, growth_pct, source_ids) values
  ('27-1021.00', 'Commercial and Industrial Designers', 'Design and develop manufactured products, such as cars, home appliances, and children''s toys. Combine artistic talent with research on product use, marketing, and materials to create the most functional and appealing product design.', 4, 83910, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1022.00', 'Fashion Designers', 'Design clothing and accessories. Create original designs or adapt fashion trends.', 3, 80960, 0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1024.00', 'Graphic Designers', 'Design or create graphics to meet specific commercial or promotional needs, such as packaging, displays, or logos. May use a variety of mediums to achieve artistic or decorative effects.', 4, 62960, -1.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1025.00', 'Interior Designers', 'Plan, design, and furnish the internal space of rooms or buildings. Design interior environments or create physical layouts that are practical, aesthetic, and conducive to the intended purposes. May specialize in a particular field, style, or phase of interior design.', 4, 67190, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1026.00', 'Merchandise Displayers and Window Trimmers', 'Plan and erect commercial displays, such as those in windows and interiors of retail stores and at trade exhibitions.', 3, 39390, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1027.00', 'Set and Exhibit Designers', 'Design special exhibits and sets for film, video, television, and theater productions. May study scripts, confer with directors, and conduct research to determine appropriate architectural styles.', 5, 75240, 1.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.00', 'Producers and Directors', 'Produce or direct stage, television, radio, video, or film productions for entertainment, information, or instruction. Responsible for creative decisions, such as interpretation of script, choice of actors or guests, set design, sound, special effects, and choreography.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.03', 'Media Programming Directors', 'Direct and coordinate activities of personnel engaged in preparation of radio or television station program schedules and programs, such as sports or news.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.04', 'Talent Directors', 'Audition and interview performers to select most appropriate talent for parts in stage, television, radio, or motion picture productions.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.05', 'Media Technical Directors/Managers', 'Coordinate activities of technical departments, such as taping, editing, engineering, and maintenance, to produce radio or television programs.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2022.00', 'Coaches and Scouts', 'Instruct or coach groups or individuals in the fundamentals of sports for the primary purpose of competition. Demonstrate techniques and methods of participation. May evaluate athletes'' strengths and weaknesses as possible recruits or to improve the athletes'' technique to prepare them for competition. Those required to hold teaching certifications should be reported in the appropriate teaching category.', 4, 47320, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2031.00', 'Dancers', 'Perform dances. May perform on stage, for broadcasting, or for video recording.', 3, null, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2032.00', 'Choreographers', 'Create new dance routines. Rehearse performance of routines. May direct and stage presentations.', 3, 55310, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2041.00', 'Music Directors and Composers', 'Conduct, direct, plan, and lead instrumental or vocal performances by musical artists or groups, such as orchestras, bands, choirs, and glee clubs; or create original works of music.', 4, 73710, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2042.00', 'Musicians and Singers', 'Play one or more musical instruments or sing. May perform on stage, for broadcasting, or for sound or video recording.', 4, null, 0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3011.00', 'Broadcast Announcers and Radio Disc Jockeys', 'Speak or read from scripted materials, such as news reports or commercial messages, on radio, television, or other communications media. May play and queue music, announce artist or title of performance, identify station, or interview guests.', 4, 47340, -7.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3023.00', 'News Analysts, Reporters, and Journalists', 'Narrate or write news stories, reviews, or commentary for print, broadcast, or other communications media such as newspapers, magazines, radio, or television. May collect and analyze information through interview, investigation, or observation.', 4, 62200, -5.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3031.00', 'Public Relations Specialists', 'Promote or create an intended public image for individuals, groups, or organizations. May write or select material for release to various communications media. May specialize in using social media.', 4, 74750, 1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3041.00', 'Editors', 'Plan, coordinate, revise, or edit written material. May review proposals and drafts for possible publication.', 4, 77920, -1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3042.00', 'Technical Writers', 'Write technical materials, such as equipment manuals, appendices, or operating and maintenance instructions. May assist in layout work.', 4, 90390, 0.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3043.00', 'Writers and Authors', 'Originate and prepare written material, such as scripts, stories, advertisements, and other material.', 4, 76910, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3043.05', 'Poets, Lyricists and Creative Writers', 'Create original written works, such as scripts, essays, prose, poetry or song lyrics, for publication or performance.', 4, 76910, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3091.00', 'Interpreters and Translators', 'Interpret oral or sign language, or translate written text from one language into another.', 4, 60170, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3092.00', 'Court Reporters and Simultaneous Captioners', 'Use verbatim methods and equipment to capture, store, retrieve, and transcribe pretrial and trial proceedings or other information. Includes stenocaptioners who operate computerized stenographic captioning equipment to provide captions of live or prerecorded broadcasts for hearing-impaired viewers.', 3, 72420, -0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4011.00', 'Audio and Video Technicians', 'Set up, maintain, and dismantle audio and video equipment, such as microphones, sound speakers, connecting wires and cables, sound and mixing boards, video cameras, video monitors and servers, and related electronic equipment for live or recorded events, such as concerts, meetings, conventions, presentations, podcasts, news conferences, and sporting events.', 3, 58100, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4012.00', 'Broadcast Technicians', 'Set up, operate, and maintain the electronic equipment used to acquire, edit, and transmit audio and video for radio or television programs. Control and adjust incoming and outgoing broadcast signals to regulate sound volume, signal strength, and signal clarity. Operate satellite, microwave, or other transmitter equipment to broadcast radio or television programs.', 3, 59570, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4014.00', 'Sound Engineering Technicians', 'Assemble and operate equipment to record, synchronize, mix, edit, or reproduce sound, including music, voices, or sound effects, for theater, video, film, television, podcasts, sporting events, and other productions.', 3, 73130, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4015.00', 'Lighting Technicians', 'Set up, maintain, and dismantle light fixtures, lighting control devices, and the associated lighting electrical and rigging equipment used for photography, television, film, video, and live productions. May focus or operate light fixtures, or attach color filters or other lighting accessories.', 3, 68060, -4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4021.00', 'Photographers', 'Photograph people, landscapes, merchandise, or other subjects. May use lighting equipment to enhance a subject''s appearance. May use editing software to produce finished images and prints. Includes commercial and industrial photographers, scientific photographers, and photojournalists.', 3, 44660, -0.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4031.00', 'Camera Operators, Television, Video, and Film', 'Operate television, video, or film camera to record images or scenes for television, video, or film productions.', 3, 74990, 1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4032.00', 'Film and Video Editors', 'Edit moving images on film, video, or other media. May work with a producer or director to organize images for final production. May edit or synchronize soundtracks with images.', 4, 75420, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1011.00', 'Chiropractors', 'Assess, treat, and care for patients by manipulation of spine and musculoskeletal system. May provide spinal adjustment or address sacral or pelvic misalignment.', 5, 79200, 8.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1021.00', 'Dentists, General', 'Examine, diagnose, and treat diseases, injuries, and malformations of teeth and gums. May treat diseases of nerve, pulp, and other dental tissues affecting oral hygiene and retention of teeth. May fit dental appliances or provide preventive care.', 5, 170950, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1022.00', 'Oral and Maxillofacial Surgeons', 'Perform surgery and related procedures on the hard and soft tissues of the oral and maxillofacial regions to treat diseases, injuries, or defects. May diagnose problems of the oral and maxillofacial regions. May perform surgery to improve function or appearance.', 5, 352220, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1023.00', 'Orthodontists', 'Examine, diagnose, and treat dental malocclusions and oral cavity anomalies. Design and fabricate appliances to realign teeth and jaws to produce and maintain normal function and to improve appearance.', 5, 289140, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1024.00', 'Prosthodontists', 'Diagnose, treat, rehabilitate, design, and fit prostheses that maintain oral function, health, and appearance for patients with clinical conditions associated with teeth, oral and maxillofacial tissues, or the jaw.', 5, 311180, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1031.00', 'Dietitians and Nutritionists', 'Plan and conduct food service or nutritional programs to assist in the promotion of health and control of disease. May supervise activities of a department providing quantity food services, counsel individuals, or conduct nutritional research.', 5, 76400, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1041.00', 'Optometrists', 'Diagnose, manage, and treat conditions and diseases of the human eye and visual system. Examine eyes and visual system, diagnose problems or impairments, prescribe corrective lenses, and provide treatment. May prescribe therapeutic drugs to treat specific eye conditions.', 5, 136570, 9.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1051.00', 'Pharmacists', 'Dispense drugs prescribed by physicians and other health practitioners and provide information to patients about medications and their use. May advise physicians and other health practitioners on the selection, dosage, interactions, and side effects of medications.', 5, 140910, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1071.00', 'Physician Assistants', 'Provide healthcare services typically performed by a physician, under the supervision of a physician. Conduct complete physicals, provide treatment, and counsel patients. May, in some cases, prescribe medication. Must graduate from an accredited educational program for physician assistants.', 5, 135880, 21.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1071.01', 'Anesthesiologist Assistants', 'Assist anesthesiologists in the administration of anesthesia for surgical and non-surgical procedures. Monitor patient status and provide patient care during surgical treatment.', 5, 135880, 21.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1081.00', 'Podiatrists', 'Diagnose and treat diseases and deformities of the human foot.', 5, 160300, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1122.00', 'Occupational Therapists', 'Assess, plan, and organize rehabilitative programs that help build or restore vocational, homemaking, and daily living skills, as well as general independence, to persons with disabilities or developmental delays. Use therapeutic techniques, adapt the individual''s environment, teach skills, and modify specific tasks that present barriers to the individual.', 5, 100330, 14.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1122.01', 'Low Vision Therapists, Orientation and Mobility Specialists, and Vision Rehabilitation Therapists', 'Provide therapy to patients with visual impairments to improve their functioning in daily life activities. May train patients in activities such as computer use, communication skills, or home management skills.', 5, 100330, 14.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1123.00', 'Physical Therapists', 'Assess, plan, organize, and participate in rehabilitative programs that improve mobility, relieve pain, increase strength, and improve or correct disabling conditions resulting from disease or injury.', 5, 102760, 11.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1124.00', 'Radiation Therapists', 'Provide radiation therapy to patients as prescribed by a radiation oncologist according to established practices and standards. Duties may include reviewing prescription and diagnosis; acting as liaison with physician and supportive care personnel; preparing equipment, such as immobilization, treatment, and protection devices; and maintaining records, reports, and files. May assist in dosimetry procedures and tumor localization.', 3, 105310, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1125.00', 'Recreational Therapists', 'Plan, direct, or coordinate medically-approved recreation programs for patients in hospitals, nursing homes, or other institutions. Activities include sports, trips, dramatics, social activities, and crafts. May assess a patient condition and recommend appropriate recreational activity.', 4, 61960, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1126.00', 'Respiratory Therapists', 'Assess, treat, and care for patients with breathing disorders. Assume primary responsibility for all respiratory care modalities, including the supervision of respiratory therapy technicians. Initiate and conduct therapeutic procedures; maintain patient records; and select, assemble, check, and operate equipment.', 3, 82280, 8.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1127.00', 'Speech-Language Pathologists', 'Assess and treat persons with speech, language, voice, and fluency disorders. May select alternative communication systems and teach their use. May perform research related to speech and language problems.', 5, 97870, 16.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1128.00', 'Exercise Physiologists', 'Assess, plan, or implement fitness programs that include exercise or physical activities such as those designed to improve cardiorespiratory function, body composition, muscular strength, muscular endurance, or flexibility.', 4, 59460, 12.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1129.01', 'Art Therapists', 'Plan or conduct art therapy sessions or programs to improve clients'' physical, cognitive, or emotional well-being.', 5, 77930, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1129.02', 'Music Therapists', 'Plan, organize, direct, or assess clinical and evidenced-based music therapy interventions to positively influence individuals'' physical, psychological, cognitive, or behavioral status.', 4, 77930, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1131.00', 'Veterinarians', 'Diagnose, treat, or research diseases and injuries of animals. Includes veterinarians who conduct research and development, inspect livestock, or care for pets and companion animals.', 5, 130100, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.00', 'Registered Nurses', 'Assess patient health problems and needs, develop and implement nursing care plans, and maintain medical records. Administer nursing care to ill, injured, convalescent, or disabled patients. May advise patients on health maintenance and disease prevention or provide case management. Licensing or registration required.', 4, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.01', 'Acute Care Nurses', 'Provide advanced nursing care for patients with acute conditions such as heart attacks, respiratory distress syndrome, or shock. May care for pre- and post-operative patients or perform advanced, invasive diagnostic or therapeutic procedures.', 4, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.02', 'Advanced Practice Psychiatric Nurses', 'Assess, diagnose, and treat individuals and families with mental health or substance use disorders or the potential for such disorders. Apply therapeutic activities, including the prescription of medication, per state regulations, and the administration of psychotherapy.', 5, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.03', 'Critical Care Nurses', 'Provide specialized nursing care for patients in critical or coronary care units.', 4, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.04', 'Clinical Nurse Specialists', 'Direct nursing staff in the provision of patient care in a clinical practice setting, such as a hospital, hospice, clinic, or home. Ensure adherence to established clinical policies, protocols, regulations, and standards.', 5, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1151.00', 'Nurse Anesthetists', 'Administer anesthesia, monitor patient''s vital signs, and oversee patient recovery from anesthesia. May assist anesthesiologists, surgeons, other physicians, or dentists. Must be registered nurses who have specialized graduate education.', 5, 236590, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1161.00', 'Nurse Midwives', 'Diagnose and coordinate all aspects of the birthing process, either independently or as part of a healthcare team. May provide well-woman gynecological care. Must have specialized, graduate nursing education.', 5, 134040, 11.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1171.00', 'Nurse Practitioners', 'Diagnose and treat acute, episodic, or chronic illness, independently or as part of a healthcare team. May focus on health promotion and disease prevention. May order, perform, or interpret diagnostic tests such as lab work and x rays. May prescribe medication. Must be registered nurses who have specialized graduate education.', 5, 132300, 41, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1181.00', 'Audiologists', 'Assess and treat persons with hearing and related disorders. May fit hearing aids and provide auditory training. May perform research related to hearing problems.', 5, 95780, 11, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1211.00', 'Anesthesiologists', 'Administer anesthetics and analgesics for pain management prior to, during, or after surgery.', 5, 391490, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1212.00', 'Cardiologists', 'Diagnose, treat, manage, and prevent diseases or conditions of the cardiovascular system. May further subspecialize in interventional procedures (e.g., balloon angioplasty and stent placement), echocardiography, or electrophysiology.', 5, 496010, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1213.00', 'Dermatologists', 'Diagnose and treat diseases relating to the skin, hair, and nails. May perform both medical and dermatological surgery functions.', 5, 328730, 6.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1214.00', 'Emergency Medicine Physicians', 'Make immediate medical decisions and act to prevent death or further disability. Provide immediate recognition, evaluation, care, stabilization, and disposition of patients. May direct emergency medical staff in an emergency department.', 5, 335550, 3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1215.00', 'Family Medicine Physicians', 'Diagnose, treat, and provide preventive care to individuals and families across the lifespan. May refer patients to specialists when needed for further diagnosis or treatment.', 5, 244180, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1216.00', 'General Internal Medicine Physicians', 'Diagnose and provide nonsurgical treatment for a wide range of diseases and injuries of internal organ systems. Provide care mainly for adults and adolescents, and are based primarily in an outpatient care setting.', 5, 256560, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1217.00', 'Neurologists', 'Diagnose, manage, and treat disorders and diseases of the brain, spinal cord, and peripheral nerves, with a primarily nonsurgical focus.', 5, 248560, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1218.00', 'Obstetricians and Gynecologists', 'Provide medical care related to pregnancy or childbirth. Diagnose, treat, and help prevent diseases of women, particularly those affecting the reproductive system. May also provide general care to women. May perform both medical and gynecological surgery functions.', 5, 292910, 1.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1221.00', 'Pediatricians, General', 'Diagnose, treat, and help prevent diseases and injuries in children. May refer patients to specialists for further diagnosis or treatment, as needed.', 5, 210040, 1.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1222.00', 'Physicians, Pathologists', 'Diagnose diseases and conduct lab tests using organs, body tissues, and fluids. Includes medical examiners.', 5, 312400, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1223.00', 'Psychiatrists', 'Diagnose, treat, and help prevent mental disorders.', 5, 281870, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1224.00', 'Radiologists', 'Diagnose and treat diseases and injuries using medical imaging techniques, such as x rays, magnetic resonance imaging (MRI), nuclear medicine, and ultrasounds. May perform minimally invasive medical procedures and tests.', 5, 420860, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.01', 'Allergists and Immunologists', 'Diagnose, treat, and help prevent allergic diseases and disease processes affecting the immune system.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.02', 'Hospitalists', 'Provide inpatient care predominantly in settings such as medical wards, acute care units, intensive care units, rehabilitation centers, or emergency rooms. Manage and coordinate patient care throughout treatment.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.03', 'Urologists', 'Diagnose, treat, and help prevent benign and malignant medical and surgical disorders of the genitourinary system and the renal glands.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.04', 'Physical Medicine and Rehabilitation Physicians', 'Diagnose and treat disorders requiring physiotherapy to provide physical, mental, and occupational rehabilitation.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.05', 'Preventive Medicine Physicians', 'Apply knowledge of general preventive medicine and public health issues to promote health care to groups or individuals, and aid in the prevention or reduction of risk of disease, injury, disability, or death. May practice population-based medicine or diagnose and treat patients in the context of clinical health promotion and disease prevention.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.06', 'Sports Medicine Physicians', 'Diagnose, treat, and help prevent injuries that occur during sporting events, athletic training, and physical activities.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1241.00', 'Ophthalmologists, Except Pediatric', 'Diagnose and perform surgery to treat and help prevent disorders and diseases of the eye. May also provide vision services for treatment including glasses and contacts.', 5, 300080, 4.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1242.00', 'Orthopedic Surgeons, Except Pediatric', 'Diagnose and perform surgery to treat and prevent rheumatic and other diseases in the musculoskeletal system.', 5, 358550, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1243.00', 'Pediatric Surgeons', 'Diagnose and perform surgery to treat fetal abnormalities and birth defects, diseases, and injuries in fetuses, premature and newborn infants, children, and adolescents. Includes all pediatric surgical specialties and subspecialties.', 5, 559030, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1291.00', 'Acupuncturists', 'Diagnose, treat, and prevent disorders by stimulating specific acupuncture points within the body using acupuncture needles. May also use cups, nutritional supplements, therapeutic massage, acupressure, and other alternative health therapies.', 5, 76040, 8.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1292.00', 'Dental Hygienists', 'Administer oral hygiene care to patients. Assess patient oral hygiene problems or needs and maintain health records. Advise patients on oral health maintenance and disease prevention. May provide advanced care such as providing fluoride treatment or administering topical anesthesia.', 3, 98100, 8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1299.01', 'Naturopathic Physicians', 'Diagnose, treat, and help prevent diseases using a system of practice that is based on the natural healing capacity of individuals. May use physiological, psychological or mechanical methods. May also use natural medicines, prescription or legend drugs, foods, herbs, or other natural remedies.', 5, 115210, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1299.02', 'Orthoptists', 'Diagnose and treat visual system disorders such as binocular vision and eye movement impairments.', 5, 115210, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.00', 'Medical and Clinical Laboratory Technologists', 'Perform complex medical laboratory tests for diagnosis, treatment, and prevention of disease. May train or supervise staff.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.01', 'Cytogenetic Technologists', 'Analyze chromosomes or chromosome segments found in biological specimens, such as amniotic fluids, bone marrow, solid tumors, and blood to aid in the study, diagnosis, classification, or treatment of inherited or acquired genetic diseases. Conduct analyses through classical cytogenetic, fluorescent in situ hybridization (FISH) or array comparative genome hybridization (aCGH) techniques.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.02', 'Cytotechnologists', 'Stain, mount, and study cells to detect evidence of cancer, hormonal abnormalities, and other pathological conditions following established standards and practices.', 5, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.04', 'Histotechnologists', 'Apply knowledge of health and disease causes to evaluate new laboratory techniques and procedures to examine tissue samples. Process and prepare histological slides from tissue sections for microscopic examination and diagnosis by pathologists. May solve technical or instrument problems or assist with research studies.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2012.00', 'Medical and Clinical Laboratory Technicians', 'Perform routine medical laboratory tests for the diagnosis, treatment, and prevention of disease. May work under the supervision of a medical technologist.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2012.01', 'Histology Technicians', 'Prepare histological slides from tissue sections for microscopic examination and diagnosis by pathologists. May assist with research studies.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2031.00', 'Cardiovascular Technologists and Technicians', 'Conduct tests on pulmonary or cardiovascular systems of patients for diagnostic, therapeutic, or research purposes. May conduct or assist in electrocardiograms, cardiac catheterizations, pulmonary functions, lung capacity, and similar tests.', 3, 74310, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2032.00', 'Diagnostic Medical Sonographers', 'Produce ultrasonic recordings of internal organs for use by physicians. Includes vascular technologists.', 3, 96590, 13.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2033.00', 'Nuclear Medicine Technologists', 'Prepare, administer, and measure radioactive isotopes in therapeutic, diagnostic, and tracer studies using a variety of radioisotope equipment. Prepare stock solutions of radioactive materials and calculate doses to be administered by radiologists. Subject patients to radiation. Execute blood volume, red cell survival, and fat absorption studies following standard laboratory techniques.', 3, 101370, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2034.00', 'Radiologic Technologists and Technicians', 'Take x-rays and CAT scans or administer nonradioactive materials into patient''s bloodstream for diagnostic or research purposes. Includes radiologic technologists and technicians who specialize in other scanning modalities.', 3, 80110, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2035.00', 'Magnetic Resonance Imaging Technologists', 'Operate Magnetic Resonance Imaging (MRI) scanners. Monitor patient safety and comfort, and view images of area being scanned to ensure quality of pictures. May administer gadolinium contrast dosage intravenously. May interview patient, explain MRI procedures, and position patient on examining table. May enter into the computer data such as patient history, anatomical area to be scanned, orientation specified, and position of entry.', 3, 95480, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2036.00', 'Medical Dosimetrists', 'Generate radiation treatment plans, develop radiation dose calculations, communicate and supervise the treatment plan implementation, and consult with members of radiation oncology team.', 4, 147470, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2042.00', 'Emergency Medical Technicians', 'Assess injuries and illnesses and administer basic emergency medical care. May transport injured or sick persons to medical facilities.', 3, 44470, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2'])
